// Compute overallScore from scorecard for each tool
export const CURATED_TOOLS: CuratedTool[] = raw.map((t) => ({
    ...t,
    overallScore: computeOverall(t.scorecard),
}));

export const TOOL_CATEGORIES = Array.from(
    new Set(CURATED_TOOLS.flatMap((t) => t.tags))
).sort();

export const PRIMARY_CATEGORIES = Array.from(
    new Set(CURATED_TOOLS.map((t) => t.category))
).sort();

